import {
  ArrowLeft,
  BookOpenText,
  ChevronRight,
  Clock3,
  Search,
} from "lucide-react";
import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { BOOK_COVER_IMAGES, BOOKS, type BookDefinition } from "../study/books";
import CircularGallery from "../reactbits/vendor/CircularGallery/CircularGallery";
import Counter from "../reactbits/vendor/Counter/Counter";
import SpotlightCard from "../reactbits/vendor/SpotlightCard/SpotlightCard";
import { AmbientBackdrop } from "../ambient/AmbientBackdrop";
import "./library-shelf.css";

type LibraryBookItem = {
  src: string;
  alt: string;
  title: string;
  subtitle: string;
  bookId: string;
};

function matchesQuery(book: BookDefinition, query: string) {
  return `${book.title} ${book.zhTitle} ${book.author}`
    .toLowerCase()
    .includes(query.toLowerCase());
}

export function SpaceLibrary() {
  const navigate = useNavigate();
  const [query, setQuery] = useState("");

  const filteredBooks = useMemo(
    () => BOOKS.filter((book) => matchesQuery(book, query)),
    [query],
  );

  const items = useMemo<LibraryBookItem[]>(
    () =>
      filteredBooks.map((book) => ({
        src: BOOK_COVER_IMAGES[book.id],
        alt: `${book.title} book cover`,
        title: book.zhTitle,
        subtitle: `${book.title} · ${book.author}`,
        bookId: book.id,
      })),
    [filteredBooks],
  );

  return (
    <div className="library-shelf-page library-shelf-page--stream">
      <header className="shelf-header" data-motion="enter">
        <button
          type="button"
          className="shelf-back"
          onClick={() => navigate("/shelf")}
          aria-label="返回首页"
        >
          <ArrowLeft size={18} />
        </button>
        <div>
          <span className="eyebrow">Library · 阅读藏书</span>
          <h1>我的书架</h1>
          <p>横向拖动浏览，点击书籍直接打开阅读。</p>
        </div>
        <button
          type="button"
          className="shelf-new"
          onClick={() => navigate("/reading")}
        >
          <BookOpenText size={15} />
          章节阅读
        </button>
      </header>

      <label className="shelf-search" data-motion="enter">
        <Search size={17} />
        <input
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="搜索书名或作者…"
        />
        <Counter
          value={filteredBooks.length}
          fontSize={18}
          gap={1}
          horizontalPadding={0}
          gradientHeight={0}
          textColor="#4f5670"
          fontWeight={700}
        />
      </label>

      <section className="library-stream" aria-label="阅读书籍">
        {items.length > 0 ? (
          <div className="library-curved-gallery">
            <CircularGallery
              items={items.map((item) => ({
                image: item.src,
                text: item.title,
              }))}
              bend={2.4}
              borderRadius={0.04}
              textColor="#4f554f"
              scrollSpeed={2.2}
              scrollEase={0.06}
              onItemSelect={(index) => {
                const book = items[index];
                if (book) navigate(`/book/${book.bookId}`);
              }}
            />
          </div>
        ) : (
          <AmbientBackdrop
            className="library-stream__empty"
            variant="clouds"
            active
          >
            没有匹配的书籍。
          </AmbientBackdrop>
        )}
      </section>

      <section className="shelf-recent" data-motion="enter">
        <div className="section-heading-row">
          <div>
            <span className="eyebrow">Recently opened</span>
            <h2>继续阅读</h2>
          </div>
          <Clock3 size={17} />
        </div>
        <div className="recent-note-list" data-motion="stagger">
          {filteredBooks.slice(0, 5).map((book) => (
            <SpotlightCard
              key={book.id}
              as="button"
              className="recent-note-row"
              onClick={() => navigate(`/book/${book.id}`)}
              spotlightColor="rgba(47, 135, 171, 0.12)"
            >
              <img
                className="recent-note-row__cover"
                src={BOOK_COVER_IMAGES[book.id]}
                alt=""
              />
              <span>
                <strong>{book.zhTitle}</strong>
                <small>
                  {book.title} · {book.author}
                </small>
              </span>
              <ChevronRight size={16} />
            </SpotlightCard>
          ))}
        </div>
      </section>
    </div>
  );
}
